//go:build ignore

// Command gen is the roadmap tool. docs/roadmap/tickets.json is the single
// source of truth: README.md, features/*.md and plan.html are generated from
// it, and so are the GitHub issues. Never hand-edit a generated file.
//
// Run from the repo root:
//
//	go run docs/roadmap/gen.go docs                  # regenerate the docs
//	go run docs/roadmap/gen.go check                 # fail if data is invalid or docs are stale
//	go run docs/roadmap/gen.go check -json           # same, as one JSON document (scripts/check.sh --json)
//	go run docs/roadmap/gen.go issues -repo owner/name -phases 1,2,3,4 [-dry-run] [-update]
//
// The issues command is idempotent: every issue carries a hidden
// "<!-- roadmap:KEY -->" marker, so re-running it only creates what is
// missing. With -update it also rewrites the title, body and labels of
// issues that already exist. Issue numbers are recorded in
// github-issues.json, which the docs use for links.
package main

import (
	"bytes"
	"cmp"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"html"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"time"
)

const (
	dir          = "docs/roadmap"
	ticketsFile  = dir + "/tickets.json"
	issuesFile   = dir + "/github-issues.json"
	templateFile = dir + "/plan.template.html"
	archFile     = dir + "/architecture.svg"
	generatedMsg = "Generated by `go run docs/roadmap/gen.go docs` from tickets.json. Do not edit by hand."
)

// ---- data model (mirrors tickets.json) ----

type Ticket struct {
	Key          string   `json:"key"`
	Title        string   `json:"title"`
	Type         string   `json:"type"`
	Estimate     string   `json:"estimate"`
	Body         string   `json:"body"`
	Requirements []string `json:"requirements"`
	Plan         []string `json:"plan"`
	Acceptance   []string `json:"acceptance"`
	DependsOn    []string `json:"depends_on"`
}

type Item struct {
	ID             string   `json:"id"`
	Phase          int      `json:"phase"`
	Name           string   `json:"name"`
	Lane           string   `json:"lane"`
	Label          string   `json:"label"`
	Summary        string   `json:"summary"`
	Design         []string `json:"design"`
	Touches        []string `json:"touches"`
	DependsOnItems []string `json:"depends_on_items"`
	DoneWhen       string   `json:"done_when"`
	Tickets        []Ticket `json:"tickets"`
}

// IssueMap records which GitHub issue holds each roadmap entry.
type IssueMap struct {
	Repo    string         `json:"repo"`
	Roadmap int            `json:"roadmap,omitempty"`
	Epics   map[string]int `json:"epics"`
	Tickets map[string]int `json:"tickets"`
}

type phaseMeta struct{ Name, Works, Color string }

var phases = map[int]phaseMeta{
	0: {"Already shipped", "Default-deny egress with TLS termination, secret swap, response scanning and DLP, MCP verdicts, policy long-poll and the fleet dashboard.", ""},
	1: {"Who did it", "Console SSO via Dex with 3 roles, admin audit log, policy history and rollback, per-worker tokens, user token verified on the worker in attribute mode, group-aware policy, fleet-wide user block, JSON audit logs, identity contract and CLI, and an in-process test harness whose scenarios every feature extends.", "1d6b58"},
	2: {"Proven identity", "Agent registry, RFC 8693 token service (15-minute agent-bound tokens), key manager, worker CA and mTLS, signed bundles, two-person approval with replay, scoped API keys, require-identity mode, Claude Code and Codex recipes.", "2d5d8f"},
	3: {"Act as the user", "Consent portal, OAuth broker for Google and GitHub, per-user secrets with refresh, JIT 403 with long-poll, offboarding revocation, per-user limits.", "7a4f9a"},
	4: {"Agents everywhere", "Delegation grants, park and notify, MCP gateway and registry, external hooks, admin MCP server, policy as code with canary.", "a2552e"},
	5: {"Enterprise scale", "Postgres and HA, Helm, OTel logs and traces, SIEM export, KMS, retention, direct IdP adapters.", "5b6470"},
}

var lanes = map[string]struct{ Area, Name string }{
	"agent":  {"area:harness", "Agent / harness"},
	"idp":    {"area:identity", "Identity provider"},
	"cp":     {"area:control-plane", "Control plane"},
	"worker": {"area:worker", "Worker"},
	"ext":    {"area:integrations", "Integrations"},
}

// Working days per estimate, low and high, used for the eng-week ranges.
var sizeDays = map[string][2]int{"S": {1, 2}, "M": {3, 5}, "L": {6, 10}}

func phaseLabel(p int) string { return fmt.Sprintf("P%d · %s", p, phases[p].Name) }

// ---- loaded roadmap with derived indexes ----

type Roadmap struct {
	Items        []*Item
	byID         map[string]*Item
	ticket       map[string]*Ticket
	owner        map[string]*Item
	unblocks     map[string][]string // ticket key -> keys that depend on it
	itemUnblocks map[string][]string // item id -> item ids that depend on it
	order        map[string]int      // item id -> build order position
	Issues       IssueMap
}

func load() (*Roadmap, error) {
	if _, err := os.Stat(ticketsFile); err != nil {
		return nil, fmt.Errorf("%s not found: run from the repo root", ticketsFile)
	}
	raw, err := os.ReadFile(ticketsFile)
	if err != nil {
		return nil, err
	}
	rm := &Roadmap{byID: map[string]*Item{}, ticket: map[string]*Ticket{}, owner: map[string]*Item{},
		unblocks: map[string][]string{}, itemUnblocks: map[string][]string{}, order: map[string]int{}}
	if err := json.Unmarshal(raw, &rm.Items); err != nil {
		return nil, fmt.Errorf("parse %s: %w", ticketsFile, err)
	}
	if err := rm.index(); err != nil {
		return nil, err
	}
	rm.Issues = IssueMap{Epics: map[string]int{}, Tickets: map[string]int{}}
	if b, err := os.ReadFile(issuesFile); err == nil {
		if err := json.Unmarshal(b, &rm.Issues); err != nil {
			return nil, fmt.Errorf("parse %s: %w", issuesFile, err)
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	return rm, nil
}

// index builds lookups and validates the data: unique ids and keys, known
// lanes and sizes, resolvable dependencies, no forward-phase dependencies
// and no cycles.
func (rm *Roadmap) index() error {
	var errs []string
	bad := func(f string, a ...any) { errs = append(errs, fmt.Sprintf(f, a...)) }
	labels := map[string]string{}
	for _, it := range rm.Items {
		if rm.byID[it.ID] != nil {
			bad("duplicate item id %s", it.ID)
		}
		rm.byID[it.ID] = it
		if _, ok := phases[it.Phase]; !ok {
			bad("%s: unknown phase %d", it.ID, it.Phase)
		}
		if _, ok := lanes[it.Lane]; !ok {
			bad("%s: unknown lane %q", it.ID, it.Lane)
		}
		if it.Phase > 0 {
			if it.Label == "" {
				bad("%s: missing label (feature slug)", it.ID)
			} else if prev, dup := labels[it.Label]; dup {
				bad("%s: label %q already used by %s", it.ID, it.Label, prev)
			}
			labels[it.Label] = it.ID
		}
		prefix := fmt.Sprintf("W-P%d-", it.Phase)
		for i := range it.Tickets {
			t := &it.Tickets[i]
			if rm.ticket[t.Key] != nil {
				bad("duplicate ticket key %s", t.Key)
			}
			if !strings.HasPrefix(t.Key, prefix) {
				bad("%s: key does not match phase %d", t.Key, it.Phase)
			}
			if _, ok := sizeDays[t.Estimate]; !ok {
				bad("%s: unknown estimate %q", t.Key, t.Estimate)
			}
			rm.ticket[t.Key] = t
			rm.owner[t.Key] = it
		}
	}
	for _, it := range rm.Items {
		for _, d := range it.DependsOnItems {
			dep := rm.byID[d]
			switch {
			case dep == nil:
				bad("%s depends on unknown item %s", it.ID, d)
			case dep.Phase > it.Phase:
				bad("%s (P%d) depends on later-phase item %s (P%d)", it.ID, it.Phase, d, dep.Phase)
			default:
				rm.itemUnblocks[d] = append(rm.itemUnblocks[d], it.ID)
			}
		}
		for _, t := range it.Tickets {
			for _, d := range t.DependsOn {
				if rm.ticket[d] == nil {
					bad("%s depends on unknown ticket %s", t.Key, d)
					continue
				}
				rm.unblocks[d] = append(rm.unblocks[d], t.Key)
			}
		}
	}
	if len(errs) > 0 {
		return fmt.Errorf("invalid %s:\n  %s", ticketsFile, strings.Join(errs, "\n  "))
	}
	// Build order: stable topological sort of items (Kahn), ties broken by
	// phase then file order. Also proves the item graph has no cycle.
	pos := map[string]int{}
	for i, it := range rm.Items {
		pos[it.ID] = i
	}
	indeg := map[string]int{}
	for _, it := range rm.Items {
		indeg[it.ID] = len(it.DependsOnItems)
	}
	var ready []*Item
	for _, it := range rm.Items {
		if indeg[it.ID] == 0 {
			ready = append(ready, it)
		}
	}
	for n := 0; len(ready) > 0; n++ {
		slices.SortStableFunc(ready, func(a, b *Item) int {
			if a.Phase != b.Phase {
				return a.Phase - b.Phase
			}
			return pos[a.ID] - pos[b.ID]
		})
		it := ready[0]
		ready = ready[1:]
		rm.order[it.ID] = n
		for _, u := range rm.itemUnblocks[it.ID] {
			if indeg[u]--; indeg[u] == 0 {
				ready = append(ready, rm.byID[u])
			}
		}
	}
	if len(rm.order) != len(rm.Items) {
		return fmt.Errorf("invalid %s: feature dependencies contain a cycle", ticketsFile)
	}
	// Ticket graph cycle check (DFS with colors).
	color := map[string]int{}
	var visit func(k string) bool
	visit = func(k string) bool {
		color[k] = 1
		for _, d := range rm.ticket[k].DependsOn {
			if color[d] == 1 || (color[d] == 0 && !visit(d)) {
				return false
			}
		}
		color[k] = 2
		return true
	}
	for k := range rm.ticket {
		if color[k] == 0 && !visit(k) {
			return fmt.Errorf("invalid %s: ticket dependencies contain a cycle through %s", ticketsFile, k)
		}
	}
	return nil
}

// Features returns the items of one phase in build order.
func (rm *Roadmap) Features(phase int) []*Item {
	var out []*Item
	for _, it := range rm.Items {
		if it.Phase == phase {
			out = append(out, it)
		}
	}
	slices.SortFunc(out, func(a, b *Item) int { return rm.order[a.ID] - rm.order[b.ID] })
	return out
}

func ticketTitle(it *Item, n int, t Ticket) string {
	return fmt.Sprintf("[%s %d/%d] %s", it.Name, n, len(it.Tickets), t.Title)
}

func ticketIndex(it *Item, key string) int {
	for i, t := range it.Tickets {
		if t.Key == key {
			return i + 1
		}
	}
	return 0
}

func sizeMix(ts []Ticket) string {
	var parts []string
	for _, s := range []string{"S", "M", "L"} {
		n := 0
		for _, t := range ts {
			if t.Estimate == s {
				n++
			}
		}
		if n > 0 {
			parts = append(parts, fmt.Sprintf("%d%s", n, s))
		}
	}
	return strings.Join(parts, " ")
}

type phaseStats struct {
	Features, Tickets int
	Mix               [3]int
	Weeks             [2]int
}

func (rm *Roadmap) stats(p int) phaseStats {
	var s phaseStats
	var lo, hi int
	for _, it := range rm.Items {
		if it.Phase != p {
			continue
		}
		s.Features++
		for _, t := range it.Tickets {
			s.Tickets++
			s.Mix[strings.Index("SML", t.Estimate)]++
			lo += sizeDays[t.Estimate][0]
			hi += sizeDays[t.Estimate][1]
		}
	}
	s.Weeks = [2]int{int(math.Round(float64(lo) / 5)), int(math.Round(float64(hi) / 5))}
	return s
}

// mermaid draws one phase's feature graph with indirect edges removed, plus
// any earlier-phase features it builds on.
func (rm *Roadmap) mermaid(phase int) string {
	reach := map[string]map[string]bool{}
	var walk func(seen map[string]bool, x string)
	walk = func(seen map[string]bool, x string) {
		for _, d := range rm.byID[x].DependsOnItems {
			if !seen[d] {
				seen[d] = true
				walk(seen, d)
			}
		}
	}
	for _, it := range rm.Items {
		reach[it.ID] = map[string]bool{}
		walk(reach[it.ID], it.ID)
	}
	type edge struct{ from, to string }
	var edges []edge
	nodes := map[string]bool{}
	for _, it := range rm.Features(phase) {
		nodes[it.ID] = true
		for _, d := range it.DependsOnItems {
			indirect := false
			for _, o := range it.DependsOnItems {
				if o != d && reach[o][d] {
					indirect = true
					break
				}
			}
			if !indirect {
				edges = append(edges, edge{d, it.ID})
				nodes[d] = true
			}
		}
	}
	nid := func(s string) string { return strings.ReplaceAll(s, "-", "_") }
	var b strings.Builder
	b.WriteString("flowchart LR\n")
	for p := 0; p <= phase; p++ {
		var ids []*Item
		for _, it := range rm.Features(p) {
			if nodes[it.ID] {
				ids = append(ids, it)
			}
		}
		if len(ids) == 0 {
			continue
		}
		fmt.Fprintf(&b, "  subgraph ph%d[\"%s\"]\n", p, phaseLabel(p))
		for _, it := range ids {
			fmt.Fprintf(&b, "    %s[\"%s\"]\n", nid(it.ID), it.Name)
		}
		b.WriteString("  end\n")
	}
	for _, e := range edges {
		fmt.Fprintf(&b, "  %s --> %s\n", nid(e.from), nid(e.to))
	}
	return strings.TrimRight(b.String(), "\n")
}

// ---- markdown docs ----

// writeDesign writes the "How we build it" and "Done when" sections shared by
// feature pages (h = "##") and epic issues (h = "###").
func writeDesign(b *strings.Builder, it *Item, h string) {
	writeList(b, it.Design, h+" How we build it", bullet)
	if it.DoneWhen != "" {
		fmt.Fprintf(b, "%s Done when\n\n%s\n\n", h, it.DoneWhen)
	}
}

// Item markers for writeList.
var (
	bullet   = func(int) string { return "- " }
	numbered = func(i int) string { return fmt.Sprintf("%d. ", i+1) }
	checkbox = func(int) string { return "- [ ] " }
)

// writeList writes items under heading, each prefixed by marker(i).
func writeList(b *strings.Builder, items []string, heading string, marker func(int) string) {
	if len(items) == 0 {
		return
	}
	fmt.Fprintf(b, "%s\n\n", heading)
	for i, s := range items {
		fmt.Fprintf(b, "%s%s\n", marker(i), s)
	}
	b.WriteString("\n")
}

// writeTicketSections writes a ticket's requirements, plan and acceptance
// lists; headingFmt styles each heading ("**%s**" or "### %s").
func writeTicketSections(b *strings.Builder, t Ticket, headingFmt string) {
	writeList(b, t.Requirements, fmt.Sprintf(headingFmt, "Requirements"), bullet)
	writeList(b, t.Plan, fmt.Sprintf(headingFmt, "Implementation plan"), numbered)
	writeList(b, t.Acceptance, fmt.Sprintf(headingFmt, "Acceptance criteria"), checkbox)
}

func mdCell(s string) string { return strings.ReplaceAll(s, "|", `\|`) }

// ghAnchor mirrors GitHub's heading slug rules.
func ghAnchor(s string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(s) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-', r == '_':
			b.WriteRune(r)
		case r == ' ':
			b.WriteRune('-')
		}
	}
	return b.String()
}

func (rm *Roadmap) issueURL(n int) string {
	return fmt.Sprintf("https://github.com/%s/issues/%d", rm.Issues.Repo, n)
}

func (rm *Roadmap) issueLink(n int) string {
	if n == 0 || rm.Issues.Repo == "" {
		return "—"
	}
	return fmt.Sprintf("[#%d](%s)", n, rm.issueURL(n))
}

func phaseHeading(p int) string { return fmt.Sprintf("Phase %d · %s", p, phases[p].Name) }

func phaseGate(p int) string {
	if p == 1 {
		return "Production-usable on its own: a company can run Warden with only Phase 1 and get user-attributed, SSO-administered egress control."
	}
	return "Closed when the sentence above is true on a real deployment."
}

func (rm *Roadmap) renderReadme() string {
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("# Warden roadmap\n\n<!-- %s -->\n\n", generatedMsg)
	w("Every agent request already goes through Warden. This roadmap adds **who** each request is for, lets an agent **act as that user** with consent, and gives the company a **control plane** it can run. There are five phases, and each one ships on its own.\n\n")
	w("| Start here | What it is |\n|---|---|\n")
	w("| [`plan.html`](plan.html) | The whole plan on one page: final design, phases, every feature and ticket, filterable. Open it in a browser. |\n")
	w("| [`architecture.svg`](architecture.svg) | Final design of Warden, with each part tagged by the phase that adds it. |\n")
	w("| [`features/`](features/) | One page per feature: how we build it, done-when, and the full text of every ticket. |\n")
	w("| [`conventions.md`](conventions.md) | Ticket keys, titles, labels, sizes, and how to change the roadmap. |\n")
	if rm.Issues.Roadmap != 0 {
		w("| %s | The pinned Roadmap issue on GitHub. Epics are its sub-issues; tickets are sub-issues of their epic. |\n", rm.issueLink(rm.Issues.Roadmap))
	}
	w("| [`tickets.json`](tickets.json) | The single source of truth. Edit only this file, then regenerate. |\n\n")

	w("## Final design\n\n![Warden target architecture](architecture.svg)\n\n")
	w("Grey tags exist today; coloured tags show the phase that adds each part. The core rule does not change: the agent's only route out is a worker, and real credentials never reach the agent.\n\n")

	w("## Phases\n\n| Phase | What works at the end | Features | Tickets | S / M / L | Eng-weeks |\n|---|---|---|---|---|---|\n")
	for p := 1; p <= 5; p++ {
		s := rm.stats(p)
		w("| [%s](#%s) | %s | %d | %d | %d / %d / %d | %d–%d |\n", phaseLabel(p), ghAnchor(phaseHeading(p)), mdCell(phases[p].Works), s.Features, s.Tickets, s.Mix[0], s.Mix[1], s.Mix[2], s.Weeks[0], s.Weeks[1])
	}
	w("\nEstimates assume S = 1–2, M = 3–5 and L = 6–10 working days for one engineer, summed over the tickets. If Phase 1 has to shrink, the agreed cuts are: defer JSON audit export and break-glass/backups, and ship only the admin and viewer roles.\n\n")

	for p := 1; p <= 5; p++ {
		w("## %s\n\n%s\n\n**Gate:** %s\n\n", phaseHeading(p), phases[p].Works, phaseGate(p))
		w("```mermaid\n%s\n```\n\n", rm.mermaid(p))
		w("| # | Feature | Lane | Needs first | Tickets | Epic |\n|---|---|---|---|---|---|\n")
		for i, it := range rm.Features(p) {
			var deps []string
			for _, d := range it.DependsOnItems {
				if dep := rm.byID[d]; dep.Phase > 0 {
					deps = append(deps, fmt.Sprintf("[%s](features/%s.md)", dep.Name, dep.Label))
				}
			}
			needs := strings.Join(deps, ", ")
			if needs == "" {
				needs = "—"
			}
			w("| %d | [%s](features/%s.md) | %s | %s | %d (%s) | %s |\n", i+1, mdCell(it.Name), it.Label, lanes[it.Lane].Name, needs, len(it.Tickets), sizeMix(it.Tickets), rm.issueLink(rm.Issues.Epics[it.ID]))
		}
		w("\n")
	}

	w("## Already shipped (Phase 0)\n\n")
	for _, it := range rm.Features(0) {
		w("- **%s.** %s\n", it.Name, it.Summary)
	}
	w("\n## Changing the roadmap\n\n")
	w("1. Edit [`tickets.json`](tickets.json).\n")
	w("2. Regenerate the docs: `go run docs/roadmap/gen.go docs`.\n")
	w("3. Push the change to GitHub issues: `go run docs/roadmap/gen.go issues -repo %s -phases 1,2,3,4 -update` (add `-dry-run` first to preview).\n", cmp.Or(rm.Issues.Repo, "owner/name"))
	w("4. Commit. `scripts/check.sh` fails if step 2 was skipped.\n\n")
	w("History: [`_planning/handoff.md`](_planning/handoff.md) is the note from the planning session that produced this roadmap.\n")
	return b.String()
}

func (rm *Roadmap) refLink(key string) string {
	it := rm.owner[key]
	t := rm.ticket[key]
	return fmt.Sprintf("[`%s`](%s.md#%s) %s", key, it.Label, ghAnchor(ticketHeading(it, key)), t.Title)
}

func ticketHeading(it *Item, key string) string {
	return fmt.Sprintf("%d/%d · %s", ticketIndex(it, key), len(it.Tickets), key)
}

func (rm *Roadmap) renderFeature(it *Item) string {
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("# %s\n\n<!-- %s -->\n\n", it.Name, generatedMsg)
	w("**Phase:** [%s](../README.md#%s) · **Lane:** %s · **Label:** `feature:%s` · **Epic:** %s · **Tickets:** %d (%s)\n\n",
		phaseLabel(it.Phase), ghAnchor(phaseHeading(it.Phase)), lanes[it.Lane].Name, it.Label, rm.issueLink(rm.Issues.Epics[it.ID]), len(it.Tickets), sizeMix(it.Tickets))
	w("%s\n\n", it.Summary)
	writeDesign(&b, it, "##")
	w("## Needs first\n\n")
	if len(it.DependsOnItems) == 0 {
		w("Nothing. This feature can start now.\n\n")
	}
	for _, d := range it.DependsOnItems {
		dep := rm.byID[d]
		w("- [%s](%s.md) (%s)\n", dep.Name, dep.Label, phaseLabel(dep.Phase))
	}
	if len(it.DependsOnItems) > 0 {
		w("\n")
	}
	if u := rm.itemUnblocks[it.ID]; len(u) > 0 {
		w("## Unblocks\n\n")
		for _, id := range u {
			x := rm.byID[id]
			w("- [%s](%s.md) (%s)\n", x.Name, x.Label, phaseLabel(x.Phase))
		}
		w("\n")
	}
	if len(it.Touches) > 0 {
		var ts []string
		for _, t := range it.Touches {
			ts = append(ts, "`"+t+"`")
		}
		w("## Code it touches\n\n%s\n\n", strings.Join(ts, " · "))
	}
	w("## Tickets\n\n| # | Key | Ticket | Type | Size | Depends on | Issue |\n|---|---|---|---|---|---|---|\n")
	for i, t := range it.Tickets {
		deps := strings.Join(t.DependsOn, ", ")
		if deps == "" {
			deps = "—"
		}
		w("| %d/%d | [`%s`](#%s) | %s | %s | %s | %s | %s |\n", i+1, len(it.Tickets), t.Key, ghAnchor(ticketHeading(it, t.Key)), mdCell(t.Title), t.Type, t.Estimate, deps, rm.issueLink(rm.Issues.Tickets[t.Key]))
	}
	w("\n")
	for _, t := range it.Tickets {
		w("### %s\n\n**%s**\n\n", ticketHeading(it, t.Key), t.Title)
		w("Type **%s** · Size **%s** · Issue %s\n\n%s\n\n", t.Type, t.Estimate, rm.issueLink(rm.Issues.Tickets[t.Key]), t.Body)
		writeTicketSections(&b, t, "**%s**")
		if len(t.DependsOn) > 0 {
			var ds []string
			for _, d := range t.DependsOn {
				ds = append(ds, rm.refLink(d))
			}
			w("**Depends on:** %s\n\n", strings.Join(ds, "; "))
		}
		if u := rm.unblocks[t.Key]; len(u) > 0 {
			var us []string
			for _, k := range u {
				us = append(us, rm.refLink(k))
			}
			w("**Unblocks:** %s\n\n", strings.Join(us, "; "))
		}
	}
	return strings.TrimRight(b.String(), "\n") + "\n"
}

// ---- plan.html ----

type pagePhase struct {
	P        int    `json:"p"`
	Name     string `json:"name"`
	Works    string `json:"works"`
	Features int    `json:"features"`
	Tickets  int    `json:"tickets"`
	Mix      [3]int `json:"mix"`
	Weeks    [2]int `json:"weeks"`
	Label    string `json:"label,omitempty"`
}

type pageTicket struct {
	Key          string   `json:"key"`
	Title        string   `json:"title"`
	Type         string   `json:"type"`
	Size         string   `json:"size"`
	Body         string   `json:"body"`
	Requirements []string `json:"requirements"`
	Plan         []string `json:"plan"`
	Acceptance   []string `json:"acceptance"`
	DependsOn    []string `json:"depends_on"`
	Unblocks     []string `json:"unblocks"`
	Labels       []string `json:"labels"`
	Issue        int      `json:"issue,omitempty"`
}

type pageFeature struct {
	ID       string       `json:"id"`
	Phase    int          `json:"phase"`
	Name     string       `json:"name"`
	Lane     string       `json:"lane"`
	Slug     string       `json:"slug"`
	LaneName string       `json:"lane_name"`
	Mix      string       `json:"mix"`
	Summary  string       `json:"summary"`
	Design   []string     `json:"design"`
	Touches  []string     `json:"touches"`
	DoneWhen string       `json:"done_when"`
	Depends  []string     `json:"depends"`
	Tickets  []pageTicket `json:"tickets"`
	Epic     int          `json:"epic,omitempty"`
}

func ticketLabels(it *Item, t Ticket) []string {
	return []string{phaseLabel(it.Phase), "feature:" + it.Label, lanes[it.Lane].Area, "type:" + t.Type, "size:" + t.Estimate}
}

func (rm *Roadmap) renderPlan() (string, error) {
	tpl, err := os.ReadFile(templateFile)
	if err != nil {
		return "", err
	}
	svg, err := os.ReadFile(archFile)
	if err != nil {
		return "", err
	}
	data := struct {
		Repo     string        `json:"repo"`
		Roadmap  int           `json:"roadmap,omitempty"`
		Phases   []pagePhase   `json:"phases"`
		Features []pageFeature `json:"features"`
	}{Repo: rm.Issues.Repo, Roadmap: rm.Issues.Roadmap}
	for p := 0; p <= 5; p++ {
		s := rm.stats(p)
		pp := pagePhase{P: p, Name: phases[p].Name, Works: phases[p].Works, Features: s.Features, Tickets: s.Tickets, Mix: s.Mix, Weeks: s.Weeks}
		if p > 0 {
			pp.Label = phaseLabel(p)
		}
		data.Phases = append(data.Phases, pp)
	}
	for p := 1; p <= 5; p++ {
		for _, it := range rm.Features(p) {
			f := pageFeature{ID: it.ID, Phase: it.Phase, Name: it.Name, Lane: it.Lane, Slug: it.Label, LaneName: lanes[it.Lane].Name, Mix: sizeMix(it.Tickets), Summary: it.Summary,
				Design: nonNil(it.Design), Touches: nonNil(it.Touches), DoneWhen: it.DoneWhen, Epic: rm.Issues.Epics[it.ID]}
			for _, d := range it.DependsOnItems {
				f.Depends = append(f.Depends, rm.byID[d].Name)
			}
			f.Depends = nonNil(f.Depends)
			for i, t := range it.Tickets {
				f.Tickets = append(f.Tickets, pageTicket{Key: t.Key, Title: ticketTitle(it, i+1, t), Type: t.Type, Size: t.Estimate,
					Body: t.Body, Requirements: nonNil(t.Requirements), Plan: nonNil(t.Plan), Acceptance: nonNil(t.Acceptance), DependsOn: nonNil(t.DependsOn), Unblocks: nonNil(rm.unblocks[t.Key]),
					Labels: ticketLabels(it, t), Issue: rm.Issues.Tickets[t.Key]})
			}
			data.Features = append(data.Features, f)
		}
	}
	js, err := json.Marshal(data) // default HTML escaping keeps "</script>" out of the page
	if err != nil {
		return "", err
	}
	out := string(tpl)
	for _, r := range []struct{ marker, val string }{
		{"/*__DATA__*/null", string(js)},
		{"<!--__MERMAID_P1__-->", html.EscapeString(rm.mermaid(1))},
		{"<!--__MERMAID_P2__-->", html.EscapeString(rm.mermaid(2))},
		{"<!--__ARCH_SVG__-->", inlineSVG(string(svg))},
		{"<!--__GENERATED__-->", "<!-- " + generatedMsg + " -->"},
		{"<!--__ROADMAP_LINK__-->", roadmapLink(rm)},
	} {
		if !strings.Contains(out, r.marker) {
			return "", fmt.Errorf("%s: marker %s missing", templateFile, r.marker)
		}
		out = strings.ReplaceAll(out, r.marker, r.val)
	}
	return out, nil
}

func roadmapLink(rm *Roadmap) string {
	if rm.Issues.Roadmap == 0 {
		return ""
	}
	return fmt.Sprintf(` · <a href="%s">Roadmap issue #%d</a>`, rm.issueURL(rm.Issues.Roadmap), rm.Issues.Roadmap)
}

var reStyle = regexp.MustCompile(`(?s)<style>.*?</style>`)

// inlineSVG drops the standalone file's own styles so the page's theme
// tokens style the diagram.
func inlineSVG(svg string) string {
	if i := strings.Index(svg, "<svg"); i >= 0 {
		svg = svg[i:]
	}
	svg = reStyle.ReplaceAllString(svg, "")
	return strings.TrimSpace(svg)
}

func nonNil[T any](s []T) []T {
	if s == nil {
		return []T{}
	}
	return s
}

// ---- docs / check ----

func (rm *Roadmap) render() (map[string]string, error) {
	out := map[string]string{dir + "/README.md": rm.renderReadme()}
	for _, it := range rm.Items {
		if it.Phase > 0 {
			out[dir+"/features/"+it.Label+".md"] = rm.renderFeature(it)
		}
	}
	plan, err := rm.renderPlan()
	if err != nil {
		return nil, err
	}
	out[dir+"/plan.html"] = plan
	return out, nil
}

// orphans lists feature pages on disk whose feature no longer exists.
func orphans(files map[string]string) []string {
	var out []string
	old, _ := filepath.Glob(dir + "/features/*.md")
	for _, f := range old {
		if _, ok := files[filepath.ToSlash(f)]; !ok {
			out = append(out, f)
		}
	}
	return out
}

func cmdDocs(rm *Roadmap) error {
	files, err := rm.render()
	if err != nil {
		return err
	}
	for _, f := range orphans(files) {
		if err := os.Remove(f); err != nil {
			return err
		}
	}
	if err := os.MkdirAll(dir+"/features", 0o755); err != nil {
		return err
	}
	for path, body := range files {
		if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
			return err
		}
	}
	fmt.Printf("wrote %d files\n", len(files))
	return nil
}

// stale lists the generated files that differ from what tickets.json renders.
func stale(rm *Roadmap) ([]string, error) {
	files, err := rm.render()
	if err != nil {
		return nil, err
	}
	var out []string
	for path, body := range files {
		cur, err := os.ReadFile(path)
		if err != nil || !bytes.Equal(cur, []byte(body)) {
			out = append(out, path)
		}
	}
	for _, f := range orphans(files) {
		out = append(out, f+" (orphaned)")
	}
	slices.Sort(out)
	return out, nil
}

func cmdCheck(rm *Roadmap) error {
	out, err := stale(rm)
	if err != nil {
		return err
	}
	if len(out) > 0 {
		return fmt.Errorf("roadmap docs are stale; run `go run docs/roadmap/gen.go docs`:\n  %s", strings.Join(out, "\n  "))
	}
	fmt.Println("roadmap ok")
	return nil
}

// checkResult is the machine-readable form of `check`, printed by `check -json`
// for scripts/check.sh --json (see tools/checkreport).
type checkResult struct {
	OK     bool     `json:"ok"`
	Stale  []string `json:"stale,omitempty"`
	Errors []string `json:"errors,omitempty"`
}

// cmdCheckJSON prints the check result as one JSON document on stdout. It
// returns an error when the roadmap is not ok, so the exit code matches the
// text form.
func cmdCheckJSON(rm *Roadmap, loadErr error) error {
	res := checkResult{}
	if loadErr == nil {
		var err error
		res.Stale, err = stale(rm)
		loadErr = err
	}
	if loadErr != nil {
		res.Errors = []string{loadErr.Error()}
	}
	res.OK = len(res.Stale) == 0 && len(res.Errors) == 0
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(res); err != nil {
		return err
	}
	if !res.OK {
		return errors.New("roadmap check failed")
	}
	return nil
}

// ---- GitHub issues ----

type gh struct {
	repo  string
	dry   bool
	delay time.Duration
	last  time.Time
}

// read runs a gh command that changes nothing; it runs even in dry-run.
func (g *gh) read(stdin string, args ...string) (string, error) {
	cmd := exec.Command("gh", args...)
	if stdin != "" {
		cmd.Stdin = strings.NewReader(stdin)
	}
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("gh %s: %v: %s", strings.Join(args[:min(3, len(args))], " "), err, strings.TrimSpace(errb.String()))
	}
	return out.String(), nil
}

// write runs a mutating gh command, spaced out to stay under GitHub's
// secondary rate limits. In dry-run it only prints the command.
func (g *gh) write(stdin string, args ...string) (string, error) {
	if g.dry {
		fmt.Printf("  would run: gh %s\n", strings.Join(args, " "))
		return "", nil
	}
	if wait := g.delay - time.Since(g.last); wait > 0 {
		time.Sleep(wait)
	}
	defer func() { g.last = time.Now() }()
	return g.read(stdin, args...)
}

var reMarker = regexp.MustCompile(`<!-- roadmap:(\S+) -->`)

func marker(key string) string { return "<!-- roadmap:" + key + " -->" }

type plannedIssue struct {
	key    string // ticket key, "epic:<item id>" or "roadmap"
	title  string
	labels []string
	ms     string
	body   func() string
}

// issueState is the part of an issue the generator owns.
type issueState struct {
	title, body, ms string
	labels          []string
}

// covers reports whether the issue already matches want. Labels only need to
// be present: the generator adds labels and never removes ones people added.
func (s issueState) covers(want issueState) bool {
	if s.title != want.title || strings.TrimSpace(s.body) != strings.TrimSpace(want.body) || s.ms != want.ms {
		return false
	}
	for _, l := range want.labels {
		if !slices.Contains(s.labels, l) {
			return false
		}
	}
	return true
}

func cmdIssues(rm *Roadmap, args []string) error {
	fs := flag.NewFlagSet("issues", flag.ExitOnError)
	repo := fs.String("repo", os.Getenv("REPO"), "GitHub repo as owner/name (default $REPO)")
	phaseList := fs.String("phases", "1,2,3,4", "comma-separated phases to open on GitHub")
	dry := fs.Bool("dry-run", false, "print what would change; make no changes")
	update := fs.Bool("update", false, "also rewrite title, body and labels of issues that already exist")
	delay := fs.Duration("delay", time.Second, "pause between write calls (GitHub secondary rate limits)")
	verbose := fs.Bool("v", false, "with -dry-run, also print each issue body")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *repo == "" {
		return errors.New("-repo owner/name is required")
	}
	if rm.Issues.Repo != "" && rm.Issues.Repo != *repo {
		return fmt.Errorf("%s records issues for %s, not %s", issuesFile, rm.Issues.Repo, *repo)
	}
	rm.Issues.Repo = *repo
	open := map[int]bool{}
	for _, s := range strings.Split(*phaseList, ",") {
		p, err := strconv.Atoi(strings.TrimSpace(s))
		if err != nil || p < 1 || p > 5 {
			return fmt.Errorf("bad phase %q", s)
		}
		open[p] = true
	}
	g := &gh{repo: *repo, dry: *dry, delay: *delay}

	// 1. Labels and milestones.
	fmt.Println("labels")
	type lbl struct{ name, color, desc string }
	labels := []lbl{{"roadmap", "1d6b58", "Roadmap tracking issue"}, {"epic", "d0612a", "Roadmap feature epic"}}
	for p := 1; p <= 5; p++ {
		labels = append(labels, lbl{phaseLabel(p), phases[p].Color, truncate("Roadmap phase "+strconv.Itoa(p)+": "+phases[p].Works, 100)})
	}
	for _, l := range []string{"agent", "idp", "cp", "worker", "ext"} {
		labels = append(labels, lbl{lanes[l].Area, "5b6964", "Component: " + lanes[l].Name})
	}
	for _, t := range []string{"feature", "test", "docs", "chore", "spike"} {
		labels = append(labels, lbl{"type:" + t, "c3ccc8", "Ticket type"})
	}
	for _, s := range []string{"S", "M", "L"} {
		d := sizeDays[s]
		labels = append(labels, lbl{"size:" + s, "9a6a12", fmt.Sprintf("Estimate %s: %d–%d days", s, d[0], d[1])})
	}
	for _, it := range rm.Items {
		if open[it.Phase] {
			labels = append(labels, lbl{"feature:" + it.Label, "dce9e4", truncate(it.Name, 100)})
		}
	}
	lblOut, err := g.read("", "label", "list", "--repo", *repo, "--limit", "1000", "--json", "name,color,description")
	if err != nil {
		return err
	}
	var haveLbl []lbl
	var rawLbl []struct{ Name, Color, Description string }
	if err := json.Unmarshal([]byte(lblOut), &rawLbl); err != nil {
		return err
	}
	for _, l := range rawLbl {
		haveLbl = append(haveLbl, lbl{l.Name, strings.ToLower(l.Color), l.Description})
	}
	for _, l := range labels {
		if slices.Contains(haveLbl, l) {
			continue
		}
		if _, err := g.write("", "label", "create", l.name, "--repo", *repo, "--color", l.color, "--description", l.desc, "--force"); err != nil {
			return err
		}
	}
	fmt.Println("milestones")
	msOut, err := g.read("", "api", "--paginate", "repos/"+*repo+"/milestones?state=all", "--jq", ".[].title")
	if err != nil {
		return err
	}
	haveMS := map[string]bool{}
	for _, t := range strings.Split(strings.TrimSpace(msOut), "\n") {
		haveMS[t] = true
	}
	for p := 1; p <= 5; p++ {
		if open[p] && !haveMS[phaseLabel(p)] {
			if _, err := g.write("", "api", "-X", "POST", "repos/"+*repo+"/milestones", "-f", "title="+phaseLabel(p), "-f", "description="+phases[p].Works); err != nil {
				return err
			}
			if !*dry {
				fmt.Printf("  made milestone %s\n", phaseLabel(p))
			}
		}
	}

	// 2. Existing roadmap issues, found by their hidden marker.
	listOut, err := g.read("", "issue", "list", "--repo", *repo, "--state", "all", "--limit", "2000", "--json", "number,id,title,body,labels,milestone")
	if err != nil {
		return err
	}
	var listed []struct {
		Number    int
		ID        string
		Title     string
		Body      string
		Labels    []struct{ Name string }
		Milestone *struct{ Title string }
	}
	if err := json.Unmarshal([]byte(listOut), &listed); err != nil {
		return err
	}
	num := map[string]int{}
	nodeID := map[int]string{}
	have := map[string]issueState{} // what GitHub holds now, to skip no-op edits
	for _, is := range listed {
		nodeID[is.Number] = is.ID
		if m := reMarker.FindStringSubmatch(is.Body); m != nil {
			num[m[1]] = is.Number
			st := issueState{title: is.Title, body: is.Body}
			for _, l := range is.Labels {
				st.labels = append(st.labels, l.Name)
			}
			if is.Milestone != nil {
				st.ms = is.Milestone.Title
			}
			have[m[1]] = st
		}
	}

	// 3. Plan every issue: roadmap first, then each phase in build order,
	// each epic followed by its tickets, so issue numbers follow build order.
	ref := func(n int) string {
		if n == 0 {
			return "#?"
		}
		return "#" + strconv.Itoa(n)
	}
	var plan []plannedIssue
	plan = append(plan, plannedIssue{key: "roadmap", title: "Roadmap: identity and control plane", labels: []string{"roadmap"},
		body: func() string { return rm.roadmapBody(open, num, ref) }})
	for p := 1; p <= 5; p++ {
		if !open[p] {
			continue
		}
		for _, it := range rm.Features(p) {
			plan = append(plan, plannedIssue{key: "epic:" + it.ID, title: fmt.Sprintf("[Epic] %s", it.Name),
				labels: []string{phaseLabel(p), "feature:" + it.Label, lanes[it.Lane].Area, "epic"}, ms: phaseLabel(p),
				body: func() string { return rm.epicBody(it, open, num, ref) }})
			for i, t := range it.Tickets {
				plan = append(plan, plannedIssue{key: t.Key, title: ticketTitle(it, i+1, t), labels: ticketLabels(it, t), ms: phaseLabel(p),
					body: func() string { return rm.ticketBody(it, i+1, t, open, num, ref) }})
			}
		}
	}

	save := func() error {
		rm.Issues.Roadmap = num["roadmap"]
		for k, n := range num {
			if id, ok := strings.CutPrefix(k, "epic:"); ok && rm.byID[id] != nil {
				rm.Issues.Epics[id] = n
			} else if rm.ticket[k] != nil {
				rm.Issues.Tickets[k] = n
			}
		}
		b, _ := json.MarshalIndent(rm.Issues, "", "  ")
		return os.WriteFile(issuesFile, append(b, '\n'), 0o644)
	}

	// 4. Create what is missing.
	fmt.Println("issues")
	created := map[string]bool{}
	for _, pi := range plan {
		if num[pi.key] != 0 {
			continue
		}
		args := []string{"issue", "create", "--repo", *repo, "--title", pi.title, "--body-file", "-"}
		for _, l := range pi.labels {
			args = append(args, "--label", l)
		}
		if pi.ms != "" {
			args = append(args, "--milestone", pi.ms)
		}
		body := pi.body()
		out, err := g.write(body, args...)
		if err != nil {
			return err
		}
		if *dry && *verbose {
			fmt.Printf("%s\n----\n", body)
		}
		created[pi.key] = true
		if *dry {
			continue
		}
		have[pi.key] = issueState{title: pi.title, body: body, labels: pi.labels, ms: pi.ms}
		u := strings.TrimSpace(out)
		n, err := strconv.Atoi(u[strings.LastIndex(u, "/")+1:])
		if err != nil {
			return fmt.Errorf("unexpected gh output %q", u)
		}
		num[pi.key] = n
		fmt.Printf("  made #%d %s\n", n, pi.title)
		if err := save(); err != nil {
			return err
		}
	}

	if *dry {
		fmt.Printf("dry run: %d of %d issues would be created\n", len(created), len(plan))
		if *update {
			// Preview -update: issues that exist and whose generated text differs.
			// Links to issues not yet created render as #? until they exist.
			changed := 0
			for _, pi := range plan {
				if created[pi.key] {
					continue
				}
				want := issueState{title: pi.title, body: pi.body(), labels: pi.labels, ms: pi.ms}
				if have[pi.key].covers(want) {
					continue
				}
				changed++
				fmt.Printf("would update #%d %s\n", num[pi.key], pi.title)
				if *verbose {
					fmt.Printf("%s\n----\n", want.body)
				}
			}
			fmt.Printf("dry run: %d existing issues would be updated\n", changed)
		}
		return nil
	}

	// 5. Rewrite what differs now that every number is known (cross-links,
	// unblocks). New issues only, unless -update.
	edited := 0
	for _, pi := range plan {
		if !created[pi.key] && !*update {
			continue
		}
		want := issueState{title: pi.title, body: pi.body(), labels: pi.labels, ms: pi.ms}
		if have[pi.key].covers(want) {
			continue
		}
		args := []string{"issue", "edit", strconv.Itoa(num[pi.key]), "--repo", *repo, "--title", want.title, "--body-file", "-"}
		for _, l := range want.labels {
			args = append(args, "--add-label", l)
		}
		if want.ms != "" {
			args = append(args, "--milestone", want.ms)
		}
		if _, err := g.write(want.body, args...); err != nil {
			return err
		}
		edited++
	}
	fmt.Printf("  updated %d issue bodies\n", edited)

	// 6. Hierarchy: epics under the roadmap issue, tickets under their epic.
	if err := rm.linkSubIssues(g, open, num, nodeID); err != nil {
		fmt.Fprintf(os.Stderr, "warning: sub-issues not linked: %v\n", err)
	}
	if created["roadmap"] {
		if _, err := g.write("", "issue", "pin", strconv.Itoa(num["roadmap"]), "--repo", *repo); err != nil {
			fmt.Fprintf(os.Stderr, "warning: could not pin roadmap issue: %v\n", err)
		}
	}
	if err := save(); err != nil {
		return err
	}
	fmt.Printf("done: %d created, %d already existed\n", len(created), len(plan)-len(created))
	return cmdDocs(rm)
}

func (rm *Roadmap) linkSubIssues(g *gh, open map[int]bool, num map[string]int, nodeID map[int]string) error {
	id := func(n int) (string, error) {
		if nodeID[n] != "" {
			return nodeID[n], nil
		}
		out, err := g.read("", "api", fmt.Sprintf("repos/%s/issues/%d", g.repo, n), "--jq", ".node_id")
		if err != nil {
			return "", err
		}
		nodeID[n] = strings.TrimSpace(out)
		return nodeID[n], nil
	}
	children := func(parent int) (map[int]bool, error) {
		q := fmt.Sprintf(`{repository(owner:%q,name:%q){issue(number:%d){subIssues(first:100){nodes{number}}}}}`,
			strings.Split(g.repo, "/")[0], strings.Split(g.repo, "/")[1], parent)
		out, err := g.read("", "api", "graphql", "-f", "query="+q, "--jq", ".data.repository.issue.subIssues.nodes[].number")
		if err != nil {
			return nil, err
		}
		have := map[int]bool{}
		for _, s := range strings.Fields(out) {
			n, _ := strconv.Atoi(s)
			have[n] = true
		}
		return have, nil
	}
	attach := func(parent int, kids []int) error {
		have, err := children(parent)
		if err != nil {
			return err
		}
		pid, err := id(parent)
		if err != nil {
			return err
		}
		for _, k := range kids {
			if k == 0 || have[k] {
				continue
			}
			kid, err := id(k)
			if err != nil {
				return err
			}
			const m = `mutation($p:ID!,$c:ID!){addSubIssue(input:{issueId:$p,subIssueId:$c}){issue{number}}}`
			if _, err := g.write("", "api", "graphql", "-f", "query="+m, "-f", "p="+pid, "-f", "c="+kid); err != nil {
				return err
			}
		}
		return nil
	}
	var epics []int
	for p := 1; p <= 5; p++ {
		if !open[p] {
			continue
		}
		for _, it := range rm.Features(p) {
			epics = append(epics, num["epic:"+it.ID])
			var kids []int
			for _, t := range it.Tickets {
				kids = append(kids, num[t.Key])
			}
			if err := attach(num["epic:"+it.ID], kids); err != nil {
				return err
			}
		}
	}
	if err := attach(num["roadmap"], epics); err != nil {
		return err
	}
	fmt.Println("  sub-issues linked")
	return nil
}

func truncate(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n-1]) + "…"
}

func (rm *Roadmap) docURL(path string) string {
	return fmt.Sprintf("https://github.com/%s/blob/main/docs/roadmap/%s", rm.Issues.Repo, path)
}

func (rm *Roadmap) roadmapBody(open map[int]bool, num map[string]int, ref func(int) string) string {
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("%s\n", marker("roadmap"))
	w("Every agent request already goes through Warden. This roadmap adds **who** each request is for, lets an agent **act as that user** with consent, and gives the company a **control plane** it can run.\n\n")
	w("**Docs:** [roadmap README](%s) · [final design](%s) · [plan page](%s) · [conventions](%s)\n\n",
		rm.docURL("README.md"), rm.docURL("architecture.svg"), rm.docURL("plan.html"), rm.docURL("conventions.md"))
	w("## How to read these issues\n\n")
	w("- This issue → **epics** (one per feature) → **tickets** (one PR each). Both levels are linked as sub-issues.\n")
	w("- Ticket titles read `[Feature n/N] action`: ticket n of the N tickets in that feature. Do them in order unless the body says otherwise.\n")
	w("- Every issue has a phase label (e.g. `%s`) and a milestone with the same name. Filter by either to see one phase.\n", phaseLabel(1))
	w("- `feature:*` groups a feature's tickets, `area:*` names the component, `size:S|M|L` is 1–2, 3–5 or 6–10 days.\n")
	w("- The text comes from `docs/roadmap/tickets.json`. Change it there and re-run the generator; edits made here get overwritten.\n\n")
	w("## Phases\n\n| Phase | What works at the end | Tickets | Eng-weeks |\n|---|---|---|---|\n")
	for p := 1; p <= 5; p++ {
		s := rm.stats(p)
		status := "on GitHub"
		if !open[p] {
			status = "not opened yet"
		}
		w("| **%s** (%s) | %s | %d | %d–%d |\n", phaseLabel(p), status, phases[p].Works, s.Tickets, s.Weeks[0], s.Weeks[1])
	}
	for p := 1; p <= 5; p++ {
		w("\n## %s\n\n", phaseLabel(p))
		for i, it := range rm.Features(p) {
			if open[p] {
				w("%d. %s %s · %d tickets\n", i+1, ref(num["epic:"+it.ID]), it.Name, len(it.Tickets))
			} else {
				w("%d. %s · %d tickets (not opened yet)\n", i+1, it.Name, len(it.Tickets))
			}
		}
	}
	return b.String()
}

// needsFirst renders an item's feature-level dependencies, one line each: the
// epic link when its phase is open, otherwise a plain "already shipped" note.
func (rm *Roadmap) needsFirst(it *Item, open map[int]bool, num map[string]int, ref func(int) string) string {
	var b strings.Builder
	for _, d := range it.DependsOnItems {
		dep := rm.byID[d]
		if open[dep.Phase] {
			fmt.Fprintf(&b, "- %s %s\n", ref(num["epic:"+d]), dep.Name)
		} else {
			fmt.Fprintf(&b, "- %s (%s, already shipped or not opened yet)\n", dep.Name, phaseLabel(dep.Phase))
		}
	}
	return b.String()
}

func (rm *Roadmap) epicBody(it *Item, open map[int]bool, num map[string]int, ref func(int) string) string {
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("%s\n", marker("epic:"+it.ID))
	w("**Feature** · %s · %s · %d tickets (%s) · Roadmap %s\n\n", phaseLabel(it.Phase), lanes[it.Lane].Name, len(it.Tickets), sizeMix(it.Tickets), ref(num["roadmap"]))
	w("%s\n\n", it.Summary)
	writeDesign(&b, it, "###")
	w("### Needs first\n\n")
	if len(it.DependsOnItems) == 0 {
		w("Nothing. This feature can start now.\n")
	}
	w("%s", rm.needsFirst(it, open, num, ref))
	w("\n### Tickets, in order\n\n")
	for _, t := range it.Tickets {
		w("- [ ] %s `%s` %s · %s\n", ref(num[t.Key]), t.Key, t.Title, t.Estimate)
	}
	w("\nFull design and ticket text: [docs/roadmap/features/%s.md](%s)\n", it.Label, rm.docURL("features/"+it.Label+".md"))
	return b.String()
}

func (rm *Roadmap) ticketBody(it *Item, n int, t Ticket, open map[int]bool, num map[string]int, ref func(int) string) string {
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	d := sizeDays[t.Estimate]
	w("%s\n", marker(t.Key))
	w("**%s** · Ticket %d of %d · %s · `%s` · Epic %s\n\n", it.Name, n, len(it.Tickets), phaseLabel(it.Phase), t.Key, ref(num["epic:"+it.ID]))
	w("| Type | Size | Component |\n|---|---|---|\n| %s | %s (%d–%d days) | %s |\n\n", t.Type, t.Estimate, d[0], d[1], lanes[it.Lane].Name)
	w("### What to build\n\n%s\n\n", t.Body)
	writeTicketSections(&b, t, "### %s")
	line := func(k string) string {
		o := rm.owner[k]
		if open[o.Phase] {
			return fmt.Sprintf("- %s `%s` %s", ref(num[k]), k, rm.ticket[k].Title)
		}
		return fmt.Sprintf("- `%s` %s (%s, not opened yet)", k, rm.ticket[k].Title, phaseLabel(o.Phase))
	}
	w("### Depends on\n\n")
	if len(t.DependsOn) == 0 {
		w("Nothing. This ticket can start now.\n")
	}
	for _, k := range t.DependsOn {
		w("%s\n", line(k))
	}
	if len(it.DependsOnItems) > 0 {
		w("\n### Feature needs first\n\n%s", rm.needsFirst(it, open, num, ref))
	}
	if u := rm.unblocks[t.Key]; len(u) > 0 {
		w("\n### Unblocks\n\n")
		for _, k := range u {
			w("%s\n", line(k))
		}
	}
	w("\n### Context\n\nPart of **%s**: %s\n\nFull design: [docs/roadmap/features/%s.md](%s)\n",
		it.Name, it.Summary, it.Label, rm.docURL("features/"+it.Label+".md#"+ghAnchor(ticketHeading(it, t.Key))))
	w("\n### Definition of done\n\n- [ ] One PR, merged to main behind a flag or default-off config\n- [ ] `scripts/check.sh` green, including the coverage gate\n- [ ] Acceptance criteria are covered by `test/harness` scenarios\n- [ ] A new external dependency ships a fake in `test/harness`\n- [ ] No secret, token or full request/response body in logs or test output\n")
	return b.String()
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: go run docs/roadmap/gen.go docs|check|issues [flags]")
		os.Exit(2)
	}
	rm, err := load()
	if os.Args[1] == "check" && slices.Contains(os.Args[2:], "-json") {
		if err := cmdCheckJSON(rm, err); err != nil {
			os.Exit(1)
		}
		return
	}
	if err == nil {
		switch os.Args[1] {
		case "docs":
			err = cmdDocs(rm)
		case "check":
			err = cmdCheck(rm)
		case "issues":
			err = cmdIssues(rm, os.Args[2:])
		default:
			err = fmt.Errorf("unknown command %q", os.Args[1])
		}
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "roadmap:", err)
		os.Exit(1)
	}
}
